INSERT INTO feature VALUES('indexed-data','types','Indexed data families','nominal-data','partial','notable',NULL,'Data families indexed by values, admitted at their stated indices with the header''s kind and the index binders typed; the header writes its indices as the kind `Nat -> Type` or as a named telescope `(n : Nat, i : Fin(n)) --> Type`, the type of a later index reading the earlier ones beside the parameters; a generator''s result applies the family to its parameters, in order, then to one term per index, and a result that instantiates or reorders a parameter is refused `NonUniformResult` by head uniformity, the parameter then declared as an index; a constructor written at an index takes the index''s type, in a signature and in a generator''s result alike; a constructor bound by a `let` with no type takes its generator''s result, each field replaced by the value written for it, and one of a family with parameters is refused `UnfixedParameter`, since no field fixes a parameter; a constructor at an index written as a call that computes its stated index checks, and the kernel reads it at its stated application, ascribed the call; a case on one checks each arm at its own constructor''s fields and binds past them one equation per index, from the index its constructor states to the scrutinee''s, and an arm whose constructor stands apart from the scrutinee at one of its indices is left out, at a family of several indices the one whose two ends distinct constructors head; an equation with a variable side refines its arm by the solution; an equation between two applications of one constructor of a datatype indexed by nothing, whose fields read no earlier field, splits into one path for each field the two write apart, each the transport of a reflexivity along the equation in the family that projects the field; a constructor whose field reads an earlier field owed.','kernel-core kernel-term core-term core-checker core-nbe core-sequent core-incremental surface-grammar surface-lowering surface-pretty','corpus/model/data/vectors.gandr corpus/pathological/data/vectors.gandr corpus/model/data/vector-cases.gandr corpus/model/data/vector-head.gandr corpus/pathological/data/vector-head.gandr corpus/model/data/index-telescope.gandr corpus/pathological/data/index-telescope.gandr corpus/model/data/grid-head.gandr corpus/pathological/data/grid-head.gandr corpus/model/data/injective-index.gandr corpus/pathological/data/injective-index.gandr corpus/model/data/head-uniformity.gandr corpus/pathological/data/head-uniformity.gandr','corpus/ledger/features/indexed-data.gandr','#1314');
